def field(name,label,value='',typ='text',wide=False,attrs=''):
    return f'<div class="field {"wide" if wide else ""}"><label for="{name}">{label}</label><input id="{name}" name="{name}" type="{typ}" value="{value}" {attrs}></div>'
def select(name,label,options):
    return f'<div class="field"><label for="{name}">{label}</label><select id="{name}" name="{name}">'+''.join(f'<option>{x}</option>' for x in options)+'</select></div>'
def save(name):
    return f'<div class="savebar"><p role="status" data-dirty-status>Değişiklik yok</p><button type="button" data-reset disabled>Vazgeç</button><button class="primary" type="submit" disabled>{name} kaydet</button></div><p class="form-result" role="status" hidden></p>'
def head(title,desc,scope='Seçili proje'):
    return f'<div class="section-head"><h2 tabindex="-1">{title}</h2><p>{desc}</p><p class="scope">{scope}<span class="scope-project"> · Merkez Ofis</span></p></div>'
